export const ADMIN_ACCESS_HTML = "<h1>Access</h1>\n<p class=\"sub\">Single sign-on through an OpenID Connect provider. The host verifies the <code>id_token</code> signature, because the interpreter is built without OpenSSL and cannot.</p>\n\n<div class=\"__CFW_CARD__\">\n<strong>__CFW_STATUS__</strong>\n<p class=\"sub\" style=\"margin:.4rem 0 0\">Issuer <code>__CFW_ISSUER__</code><br>\nClient ID <code>__CFW_CLIENT_ID__</code><br>\nClient secret __CFW_SECRET__ <span class=\"dim\">(the <code>OIDC_CLIENT_SECRET</code> binding, never read back here)</span></p>\n</div>\n\n<div class=\"card warn\">\n<strong>Requires the External Authentication Module</strong>\n<p class=\"sub\" style=\"margin:.4rem 0 0\">The host verifies the provider's token and hands Drupal a single-use ticket; <code>drupal/externalauth</code> is what maps that identity onto an account, and no contrib module ships in the packed tree. Install it from <strong>Extend</strong> before the first login, or a verified login has nowhere to land.</p>\n</div>\n\n<h2>Redirect URI</h2>\n<p class=\"sub\">Add this to the provider's allowed redirect list before the first login.</p>\n<div class=\"card\"><code>__CFW_REDIRECT_URI__</code></div>\n\n<h2>Where People Sign In</h2>\n<p class=\"sub\">This page printed the redirect URI and never the START url, and nothing on the site links to it -- so single sign-on could be fully configured and no visitor could reach it. Send people here, or link it from your theme's login block.</p>\n<div class=\"card\"><code>__CFW_START_URL__</code>__CFW_START_LINK__</div>\n\n<h2>Configure</h2>\n<p class=\"sub\">Saving fetches the issuer's discovery document, so a wrong issuer is reported here rather than at the first login.</p>\n<form id=\"oidc-form\">\n<input type=\"text\" name=\"issuer\" placeholder=\"https://accounts.example.com\" value=\"__CFW_ISSUER_INPUT__\" spellcheck=\"false\">\n<input type=\"text\" name=\"clientId\" placeholder=\"client id\" value=\"__CFW_CLIENT_ID_INPUT__\" spellcheck=\"false\">\n<button type=\"submit\">Save</button>\n<button type=\"button\" id=\"oidc-clear\"__CFW_CLEAR_DISABLED__>Clear</button></form>\n<p id=\"oidc-out\" class=\"sub\"></p>\n__CFW_ERROR__\n<div id=\"oidc-discovery\">__CFW_DISCOVERY__</div>\n<script>\n__CFW_SCRIPT__\n</script>\n\n<h2>What a Login Refuses</h2>\n<ul>\n<li>a signature from a key outside the provider's JWKS</li>\n<li>a token whose <code>iss</code> is not the issuer above</li>\n<li>a token whose <code>aud</code> belongs to another client of the same provider</li>\n<li>an expired token</li>\n<li>a nonce from a different login</li>\n</ul>\n<p class=\"sub\">The signing algorithm is taken from the key rather than from the token header, and the account is keyed by issuer and subject together, so a subject from a newly configured issuer cannot take over an existing account.</p>\n";

export const ADMIN_ACCESS_JS = "(function () {\n\tconst out = document.getElementById('oidc-out');\n\tconst shown = document.getElementById('oidc-discovery');\n\tfunction esc(s) {\n\t\tconst e = document.createElement('span');\n\t\te.textContent = String(s == null ? '' : s);\n\t\treturn e.innerHTML;\n\t}\n\tasync function send(url, init) {\n\t\tconst res = await fetch(url, Object.assign({ credentials: 'same-origin' }, init || {}));\n\t\tif (res.status === 401) {\n\t\t\twindow.location.href =\n\t\t\t\t'__CFW_LOGIN_PATH__?next=' + encodeURIComponent(location.pathname);\n\t\t\treturn null;\n\t\t}\n\t\tconst body = await res.json().catch(() => ({}));\n\t\tif (!res.ok || body.ok === false) throw new Error(body.error || 'HTTP ' + res.status);\n\t\treturn body;\n\t}\n\tdocument.getElementById('oidc-form').addEventListener('submit', async (e) => {\n\t\te.preventDefault();\n\t\tout.textContent = 'Saving...';\n\t\ttry {\n\t\t\tconst body = await send('/setup/oidc?action=save', {\n\t\t\t\tmethod: 'POST',\n\t\t\t\theaders: { 'content-type': 'application/x-www-form-urlencoded' },\n\t\t\t\tbody: new URLSearchParams(new FormData(e.target)).toString()\n\t\t\t});\n\t\t\tif (!body) return;\n\t\t\tout.textContent = 'Saved.';\n\t\t\tconst dd = body.discovery;\n\t\t\tshown.innerHTML = !dd\n\t\t\t\t? ''\n\t\t\t\t: dd.ok\n\t\t\t\t\t? '<div class=\"card\"><strong>Discovery</strong><p class=\"sub\" style=\"margin:.3rem 0 0\">authorization <code>' +\n\t\t\t\t\t\tesc(dd.authorization) +\n\t\t\t\t\t\t'</code><br>token <code>' +\n\t\t\t\t\t\tesc(dd.token) +\n\t\t\t\t\t\t'</code><br>jwks <code>' +\n\t\t\t\t\t\tesc(dd.jwks) +\n\t\t\t\t\t\t'</code></p></div>'\n\t\t\t\t\t: '<div class=\"card bad\"><strong>Discovery</strong><p class=\"sub\" style=\"margin:.3rem 0 0\"><span class=\"over\">' +\n\t\t\t\t\t\tesc(dd.error) +\n\t\t\t\t\t\t'</span></p></div>';\n\t\t\tdocument.getElementById('oidc-clear').disabled = false;\n\t\t} catch (err) {\n\t\t\tout.textContent = 'Refused: ' + err.message;\n\t\t}\n\t});\n\tdocument.getElementById('oidc-clear').addEventListener('click', async () => {\n\t\tif (!window.confirm('Clear the issuer and client id? Single sign-on stops working.'))\n\t\t\treturn;\n\t\tout.textContent = 'Clearing...';\n\t\ttry {\n\t\t\tif (await send('/setup/oidc?action=clear')) window.location.reload();\n\t\t} catch (err) {\n\t\t\tout.textContent = 'Refused: ' + err.message;\n\t\t}\n\t});\n})();\n";

