export const ADMIN_COMMANDS_HTML = "<h1>Commands</h1>\n<p class=\"sub\">A Drush-shaped field over the operations this site registers. __CFW_RUNNABLE__ of __CFW_TOTAL__ have a driver that can actually run here.</p>\n<form method=\"GET\" action=\"__CFW_ACTION__\">\n<input type=\"text\" name=\"op\" placeholder=\"cr, or en webform\" value=\"__CFW_SUBMITTED__\" spellcheck=\"false\">\n<button type=\"submit\">Run</button></form>\n__CFW_ERROR__\n__CFW_RESULT__\n<table><thead><tr><th>Command</th><th>What it does</th><th>Driver</th><th>Measured cost</th></tr></thead><tbody>__CFW_ROWS__</tbody></table>\n<p class=\"sub\">An operation with no driver is listed rather than hidden, and disabled rather than offered. A 501 with no named alternative is a 501 that gets retried.</p>\n";

