export const UPDB_VERIFY_PHP = "// __CFW_FIBER_SHIM__\nchdir('/drupal');\n\n$out = ['ok' => false];\n\ntry {\n\t// __CFW_UPDB_PREAMBLE__\n\n\t$reg = Drupal::service('update.update_hook_registry');\n\t$postReg = Drupal::service('update.post_update_registry');\n\t$out['installedVersions'] = $reg->getAllInstalledVersions();\n\t$out['pendingUpdates'] = [];\n\tforeach (update_get_update_list() as $module => $info) {\n\t\t$out['pendingUpdates'][$module] = array_keys($info['pending'] ?? []);\n\t}\n\t$pendingPost = [];\n\ttry {\n\t\tforeach ($postReg->getPendingUpdateFunctions() as $fn) {\n\t\t\t$pendingPost[] = $fn;\n\t\t}\n\t} catch (Throwable $e) {\n\t\t$out['postUpdateError'] = get_class($e) . ': ' . $e->getMessage();\n\t}\n\t$out['pendingPostUpdates'] = $pendingPost;\n\t$out['maintenanceMode'] = Drupal::state()->get('system.maintenance_mode') ? 1 : 0;\n\t$out['equivalentUpdates'] = $reg->getAllEquivalentUpdates();\n\t$out['clean'] = empty($pendingPost);\n\tforeach ($out['pendingUpdates'] as $module => $numbers) {\n\t\tif (!empty($numbers)) {\n\t\t\t$out['clean'] = false;\n\t\t}\n\t}\n\t$out['ok'] = true;\n} catch (Throwable $e) {\n\t$out['error'] = get_class($e) . ': ' . $e->getMessage();\n\t$out['trace'] = substr($e->getTraceAsString(), 0, 900);\n}\n\necho json_encode($out);\n";

export const VERIFY_MODULES_PHP = "\nuse Drupal\\Core\\Extension\\ExtensionDiscovery;\n\ntry {\n\t$kernel = $GLOBALS['__pw_kernel'] ?? null;\n\tif ($kernel === null || !Drupal::hasContainer()) {\n\t\techo json_encode(['ok' => false, 'error' => 'no kernel to verify against']);\n\t} else {\n\t\t// delivered code can add an extension, so the scan and every list rediscover, as a cache\n\t\t// rebuild would (a profile uploaded after the claim read as not installed)\n\t\ttry {\n\t\t\t$prop = new ReflectionProperty(ExtensionDiscovery::class, 'files');\n\t\t\t$prop->setValue(null, []);\n\t\t} catch (Throwable $e) {\n\t\t}\n\t\tforeach (['module', 'theme', 'profile'] as $type) {\n\t\t\tDrupal::service('extension.list.' . $type)->reset();\n\t\t}\n\t\t$handler = Drupal::service('module_handler');\n\t\t$handler->loadAll();\n\t\t$modules = array_keys($handler->getModuleList());\n\t\tsort($modules);\n\t\techo json_encode(['ok' => true, 'modules' => count($modules)]);\n\t}\n} catch (Throwable $e) {\n\techo json_encode(['ok' => false, 'error' => get_class($e) . ': ' . $e->getMessage()]);\n}\n";

export const WARMING_PAGE_CSS = ":root {\n\tcolor-scheme: light dark;\n}\nbody {\n\tmargin: 0;\n\tmin-height: 100vh;\n\tdisplay: grid;\n\tplace-items: center;\n\tfont:\n\t\t16px/1.5 system-ui,\n\t\t-apple-system,\n\t\t'Segoe UI',\n\t\tsans-serif;\n}\nmain {\n\tmax-width: 28rem;\n\tpadding: 2rem;\n\ttext-align: center;\n}\nh1 {\n\tfont-size: 1.25rem;\n\tmargin: 0 0 0.5rem;\n}\np {\n\tmargin: 0;\n\topacity: 0.75;\n}\n.dot {\n\tdisplay: inline-block;\n\twidth: 0.5rem;\n\theight: 0.5rem;\n\tmargin-right: 0.5rem;\n\tborder-radius: 50%;\n\tbackground: currentColor;\n\tanimation: pulse 1.2s ease-in-out infinite;\n}\n@keyframes pulse {\n\t0%,\n\t100% {\n\t\topacity: 0.25;\n\t}\n\t50% {\n\t\topacity: 1;\n\t}\n}\n@media (prefers-reduced-motion: reduce) {\n\t.dot {\n\t\tanimation: none;\n\t\topacity: 0.6;\n\t}\n}\n";

export const WARMING_PAGE_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n__CFW_REFRESH__<meta name=\"robots\" content=\"noindex\">\n<title>__CFW_TITLE__...</title>\n<style>\n__CFW_STYLE__\n</style>\n</head>\n<body>\n<main>\n<h1><span class=\"dot\"></span>__CFW_TITLE__...</h1>\n<p>__CFW_DETAIL__</p>\n<p><small>__CFW_NOTE__</small></p>\n</main>\n</body>\n</html>\n";

