export const WRITE_WORKLOAD_PHP = "\nuse Drupal\\Core\\DrupalKernel;\nuse Drupal\\Core\\Site\\Settings;\nuse Drupal\\file\\Entity\\File;\nuse Drupal\\node\\Entity\\Node;\nuse Drupal\\node\\Entity\\NodeType;\nuse Drupal\\user\\Entity\\User;\nuse Symfony\\Component\\HttpFoundation\\Request;\n\n// __CFW_FIBER_SHIM__\n// __CFW_HOST_HELPERS__\nchdir('/drupal');\n\n$opt = json_decode(__CFW_PAYLOAD__, true);\n$out = ['ok' => false, 'op' => $opt['op']];\n\n$_SERVER['HTTP_HOST'] = 'localhost';\n$_SERVER['SERVER_NAME'] = 'localhost';\n$_SERVER['SERVER_PORT'] = '80';\n$_SERVER['REQUEST_URI'] = '/';\n$_SERVER['REQUEST_METHOD'] = 'GET';\n$_SERVER['SCRIPT_NAME'] = '/index.php';\n$_SERVER['SCRIPT_FILENAME'] = '/drupal/index.php';\n$_SERVER['PHP_SELF'] = '/index.php';\n$_SERVER['DOCUMENT_ROOT'] = '/drupal';\n$_SERVER['REMOTE_ADDR'] = '127.0.0.1';\n$_SERVER['SERVER_SOFTWARE'] = 'workerd';\n$_SERVER['SERVER_PROTOCOL'] = 'HTTP/1.1';\n\ntry {\n\tif (!isset($GLOBALS['__pw_autoloader']) || !is_object($GLOBALS['__pw_autoloader'])) {\n\t\t$GLOBALS['__pw_autoloader'] = require '/drupal/autoload.php';\n\t}\n\t$autoloader = $GLOBALS['__pw_autoloader'];\n\tif (!isset($GLOBALS['__pw_kernel'])) {\n\t\t$boot = Request::create('/', 'GET');\n\t\t$kernel = new DrupalKernel('prod', $autoloader);\n\t\tDrupalKernel::bootEnvironment();\n\t\t$sitePath = DrupalKernel::findSitePath($boot);\n\t\t$kernel->setSitePath($sitePath);\n\t\tSettings::initialize('/drupal', $sitePath, $autoloader);\n\t\t$kernel->boot();\n\t\t$GLOBALS['__pw_kernel'] = $kernel;\n\t\t$out['bootedKernel'] = 1;\n\t}\n\n\tif (!defined('SAVED_NEW')) {\n\t\trequire_once '/drupal/core/includes/common.inc';\n\t}\n\n\tif (empty($GLOBALS['__cfw_schema_repaired'])) {\n\t\t$GLOBALS['__cfw_schema_repaired'] = true;\n\t\t// __CFW_SCHEMA_REPAIR__\n\t}\n\n\t$db = Drupal::database();\n\t// the driver's own counters, which the host tally cannot see: a speculative replay re-sends\n\t// buffered statements to resolve an insert id, and that is CPU the rows meter never charges\n\t$counter = function ($method) use ($db) {\n\t\treturn method_exists($db, $method) ? (int) $db->$method() : -1;\n\t};\n\t$before = [\n\t\t'statements' => $counter('statementCount'),\n\t\t'transactions' => $counter('transactionCount'),\n\t\t'speculative' => $counter('speculativeCount'),\n\t\t'replayed' => $counter('replayedStatementCount'),\n\t];\n\n\t$seq = (int) $opt['seq'];\n\t$nid = (int) $opt['nid'];\n\t$previousAccount = Drupal::currentUser()->getAccount();\n\t$admin = User::load(1);\n\tif ($admin !== null) {\n\t\tDrupal::currentUser()->setAccount($admin);\n\t}\n\n\tswitch ($opt['op']) {\n\t\tcase 'node-create':\n\t\t\t$types = array_keys(NodeType::loadMultiple());\n\t\t\t$type = in_array('page', $types, true) ? 'page' : $types[0] ?? null;\n\t\t\tif ($type === null) {\n\t\t\t\tthrow new RuntimeException('no node type exists in this site');\n\t\t\t}\n\t\t\t$node = Node::create([\n\t\t\t\t'type' => $type,\n\t\t\t\t'title' => 'Amplification ' . $seq,\n\t\t\t\t'uid' => 1,\n\t\t\t\t'status' => 1,\n\t\t\t]);\n\t\t\t$node->save();\n\t\t\t$out['id'] = (int) $node->id();\n\t\t\t$out['vid'] = (int) $node->getRevisionId();\n\t\t\tbreak;\n\n\t\tcase 'node-revision':\n\t\t\t$node = Node::load($nid);\n\t\t\tif ($node === null) {\n\t\t\t\tthrow new RuntimeException('no node ' . $nid . ' to revise');\n\t\t\t}\n\t\t\t// explicit rather than relying on the content type default, which is configuration\n\t\t\t$node->setNewRevision(true);\n\t\t\t$node->setRevisionLogMessage('amplification ' . $seq);\n\t\t\t$node->setRevisionCreationTime((int) Drupal::time()->getRequestTime());\n\t\t\t$node->setRevisionUserId(1);\n\t\t\t$node->setTitle('Amplification revised ' . $seq);\n\t\t\t$node->save();\n\t\t\t$out['id'] = (int) $node->id();\n\t\t\t$out['vid'] = (int) $node->getRevisionId();\n\t\t\tbreak;\n\n\t\tcase 'user-create':\n\t\t\t$account = User::create(['name' => 'amp' . $seq]);\n\t\t\t$account->setEmail('amp' . $seq . '@example.invalid');\n\t\t\t$account->setPassword('cfw-Amp-' . $seq . '-pass');\n\t\t\t$account->activate();\n\t\t\t$account->save();\n\t\t\t$out['id'] = (int) $account->id();\n\t\t\tbreak;\n\n\t\tcase 'file-create':\n\t\t\t// the ROW, not the bytes: a real upload also writes the stream, and that lands in MEMFS and\n\t\t\t// the R2 mirror rather than in Durable Object SQL, so it is a different meter\n\t\t\t$file = File::create([\n\t\t\t\t'uri' => 'public://amplification-' . $seq . '.txt',\n\t\t\t\t'filename' => 'amplification-' . $seq . '.txt',\n\t\t\t\t'filemime' => 'text/plain',\n\t\t\t\t'filesize' => 11,\n\t\t\t\t'status' => 1,\n\t\t\t\t'uid' => 1,\n\t\t\t]);\n\t\t\t$file->save();\n\t\t\t$out['id'] = (int) $file->id();\n\t\t\tbreak;\n\n\t\tcase 'alias-create':\n\t\t\t$alias = Drupal::entityTypeManager()\n\t\t\t\t->getStorage('path_alias')\n\t\t\t\t->create([\n\t\t\t\t\t'path' => '/node/' . ($nid > 0 ? $nid : 1),\n\t\t\t\t\t'alias' => '/amplification-' . $seq,\n\t\t\t\t\t'langcode' => 'en',\n\t\t\t\t]);\n\t\t\t$alias->save();\n\t\t\t$out['id'] = (int) $alias->id();\n\t\t\tbreak;\n\n\t\tcase 'txn-autoinc':\n\t\tcase 'txn-rowid':\n\t\t\t// THE A/B. Both tables are created by the caller and differ only in the keyword, so what this\n\t\t\t// measures is whether predictBufferedInsertId() could answer -- it refuses AUTOINCREMENT,\n\t\t\t// because that table's next id comes from sqlite_sequence rather than from max(rowid) + 1,\n\t\t\t// and the fallback replays the whole buffer through the host\n\t\t\t$table = $opt['op'] === 'txn-autoinc' ? 'amp_txn_auto' : 'amp_txn_rowid';\n\t\t\t$txn = $db->startTransaction();\n\t\t\t$db->query('INSERT INTO {' . $table . '} (v) VALUES (:v)', [':v' => 'row ' . $seq]);\n\t\t\t$out['id'] = (int) $db->lastInsertId();\n\t\t\tunset($txn);\n\t\t\t$out['table'] = $table;\n\t\t\tbreak;\n\n\t\tdefault:\n\t\t\tthrow new RuntimeException('unknown workload ' . $opt['op']);\n\t}\n\n\t$out['driver'] = [\n\t\t'statements' => $counter('statementCount') - $before['statements'],\n\t\t'transactions' => $counter('transactionCount') - $before['transactions'],\n\t\t'speculative' => $counter('speculativeCount') - $before['speculative'],\n\t\t'replayed' => $counter('replayedStatementCount') - $before['replayed'],\n\t\t// WHY each replay happened, not just how many. Two mechanisms were proposed for these on a\n\t\t// count alone and neither moved it; a reason cannot be guessed at a third time\n\t\t'refusals' => method_exists($db, 'predictionRefusals') ? $db->predictionRefusals() : [],\n\t];\n\t$out['ok'] = $out['id'] > 0;\n} catch (Throwable $e) {\n\t$out['error'] = get_class($e) . ': ' . $e->getMessage();\n\t$out['trace'] = substr($e->getTraceAsString(), 0, 900);\n} finally {\n\tif (isset($previousAccount)) {\n\t\ttry {\n\t\t\tDrupal::currentUser()->setAccount($previousAccount);\n\t\t} catch (Throwable $e2) {\n\t\t}\n\t}\n}\n\necho json_encode($out);\n";

export const XMLWRITER_FIX_PHP = "\nuse Drupal\\drupflare\\Degradation;\n\nif (!class_exists('XMLWriter', false)) {\n\t/**\n\t * Enough of libxml's writer to generate a sitemap, and no more.\n\t *\n\t * Not final: it exists so a contrib class can extend it.\n\t */\n\tclass XMLWriter\n\t{\n\t\t/** @var string the document built so far */\n\t\tprivate $cfwBuf = '';\n\n\t\t/** @var array<int, array{name: string, children: bool, text: bool}> open elements, innermost last */\n\t\tprivate $cfwStack = [];\n\n\t\t/** @var bool whether the innermost start tag is still open and can still take attributes */\n\t\tprivate $cfwOpen = false;\n\n\t\t/** @var bool whether to pretty-print */\n\t\tprivate $cfwIndent = false;\n\n\t\t/** @var string what one indent level is */\n\t\tprivate $cfwIndentString = ' ';\n\n\t\t/** @var resource|null the stream openUri() opened, or null when this writer builds in memory */\n\t\tprivate $cfwHandle = null;\n\n\t\tpublic function openMemory(): bool\n\t\t{\n\t\t\t$this->cfwReset();\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function openUri(string $uri): bool\n\t\t{\n\t\t\t$this->cfwReset();\n\t\t\t$handle = @fopen($uri, 'w');\n\t\t\tif ($handle === false) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\t$this->cfwHandle = $handle;\n\t\t\treturn true;\n\t\t}\n\n\t\t/**\n\t\t * Content written through verbatim, which is what separates this from text().\n\t\t *\n\t\t * It still counts as content: the enclosing element has been given something, so its end tag\n\t\t * stays on the same line the way it does after text().\n\t\t */\n\t\tpublic function writeRaw(string $content): bool\n\t\t{\n\t\t\t$this->cfwCloseStart();\n\t\t\t$depth = count($this->cfwStack);\n\t\t\tif ($depth > 0) {\n\t\t\t\t$this->cfwStack[$depth - 1]['text'] = true;\n\t\t\t}\n\t\t\t$this->cfwBuf .= $content;\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function setIndent(bool $enable): bool\n\t\t{\n\t\t\t$this->cfwIndent = $enable;\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function setIndentString(string $indent): bool\n\t\t{\n\t\t\t$this->cfwIndentString = $indent;\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function startDocument(\n\t\t\t?string $version = '1.0',\n\t\t\t?string $encoding = null,\n\t\t\t?string $standalone = null,\n\t\t): bool {\n\t\t\t$decl = '<?xml version=\"' . ($version ?? '1.0') . '\"';\n\t\t\tif ($encoding !== null && $encoding !== '') {\n\t\t\t\t$decl .= ' encoding=\"' . $encoding . '\"';\n\t\t\t}\n\t\t\tif ($standalone !== null && $standalone !== '') {\n\t\t\t\t$decl .= ' standalone=\"' . $standalone . '\"';\n\t\t\t}\n\t\t\t// the newline is UNCONDITIONAL, measured against libxml: it is part of the declaration\n\t\t\t// rather than part of indenting, and appears with setIndent(false) too\n\t\t\t$this->cfwBuf .= $decl . '?>' . \"\\n\";\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function writePI(string $target, string $content): bool\n\t\t{\n\t\t\t$this->cfwCloseStart();\n\t\t\t$this->cfwNewline();\n\t\t\t$this->cfwBuf .= '<?' . $target . ' ' . $content . '?>';\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function writeComment(string $content): bool\n\t\t{\n\t\t\t$this->cfwCloseStart();\n\t\t\t$this->cfwNewline();\n\t\t\t$this->cfwBuf .= '<!--' . $content . '-->';\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function startElement(string $name): bool\n\t\t{\n\t\t\t$this->cfwCloseStart();\n\t\t\t// the PARENT now has an element child, which is what decides whether its own end tag\n\t\t\t// goes on a fresh line; libxml keeps a text-only element on one line\n\t\t\t$depth = count($this->cfwStack);\n\t\t\tif ($depth > 0) {\n\t\t\t\t$this->cfwStack[$depth - 1]['children'] = true;\n\t\t\t}\n\t\t\t$this->cfwNewline();\n\t\t\t$this->cfwBuf .= '<' . $name;\n\t\t\t$this->cfwStack[] = ['name' => $name, 'children' => false, 'text' => false];\n\t\t\t$this->cfwOpen = true;\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function writeAttribute(string $name, string $value): bool\n\t\t{\n\t\t\t// silently dropping it would produce a sitemap missing its namespace, which validates\n\t\t\t// as XML and is rejected by every consumer\n\t\t\tif (!$this->cfwOpen) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\t$this->cfwBuf .= ' ' . $name . '=\"' . $this->cfwEscape($value) . '\"';\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function text(string $content): bool\n\t\t{\n\t\t\t$this->cfwCloseStart();\n\t\t\t$depth = count($this->cfwStack);\n\t\t\tif ($depth > 0) {\n\t\t\t\t$this->cfwStack[$depth - 1]['text'] = true;\n\t\t\t}\n\t\t\t$this->cfwBuf .= $this->cfwEscape($content);\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function writeElement(string $name, ?string $content = null): bool\n\t\t{\n\t\t\t$this->startElement($name);\n\t\t\t// NULL and '' differ, and libxml distinguishes them: <x/> against <x></x>\n\t\t\tif ($content !== null) {\n\t\t\t\t$this->text($content);\n\t\t\t}\n\t\t\treturn $this->endElement();\n\t\t}\n\n\t\tpublic function endElement(): bool\n\t\t{\n\t\t\tif ($this->cfwStack === []) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\t$frame = array_pop($this->cfwStack);\n\t\t\tif ($this->cfwOpen) {\n\t\t\t\t// nothing was ever written into it, so it collapses\n\t\t\t\t$this->cfwBuf .= '/>';\n\t\t\t\t$this->cfwOpen = false;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t\tif ($frame['children'] && !$frame['text']) {\n\t\t\t\t$this->cfwNewline();\n\t\t\t}\n\t\t\t$this->cfwBuf .= '</' . $frame['name'] . '>';\n\t\t\t// returning to the top level ends a line, measured: libxml emits it even with no\n\t\t\t// endDocument() at all, so it belongs to the element rather than to the document\n\t\t\tif ($this->cfwIndent && $this->cfwStack === []) {\n\t\t\t\t$this->cfwBuf .= \"\\n\";\n\t\t\t}\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function endDocument(): bool\n\t\t{\n\t\t\twhile ($this->cfwStack !== []) {\n\t\t\t\t$this->endElement();\n\t\t\t}\n\t\t\t$this->cfwCloseStart();\n\t\t\t// unconditional, but never doubled: with indent on, endElement() has already ended the\n\t\t\t// line and libxml does not add a second\n\t\t\tif ($this->cfwBuf !== '' && substr($this->cfwBuf, -1) !== \"\\n\") {\n\t\t\t\t$this->cfwBuf .= \"\\n\";\n\t\t\t}\n\t\t\t// A URI WRITER HAS TO REACH ITS FILE HERE. xmlsitemap calls endDocument() and then\n\t\t\t// file_get_contents() on the same uri to gzip it, so a buffer still held in memory\n\t\t\t// produces an empty .gz beside a sitemap that looks fine\n\t\t\tif ($this->cfwHandle !== null) {\n\t\t\t\t$this->flush(true);\n\t\t\t}\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic function outputMemory(bool $flush = true): string\n\t\t{\n\t\t\t$out = $this->cfwBuf;\n\t\t\tif ($flush) {\n\t\t\t\t$this->cfwBuf = '';\n\t\t\t\t$this->cfwStack = [];\n\t\t\t\t$this->cfwOpen = false;\n\t\t\t}\n\t\t\treturn $out;\n\t\t}\n\n\t\t/**\n\t\t * BYTES for a uri writer and the DOCUMENT for a memory one, which is libxml own split.\n\t\t *\n\t\t * Returning the string in both cases would read as working: xmlsitemap ignores the return of\n\t\t * its periodic flushes, so the file would simply stay empty until something read it.\n\t\t */\n\t\tpublic function flush(bool $empty = true)\n\t\t{\n\t\t\tif ($this->cfwHandle === null) {\n\t\t\t\treturn $this->outputMemory($empty);\n\t\t\t}\n\t\t\t$written = fwrite($this->cfwHandle, $this->cfwBuf);\n\t\t\tif ($empty) {\n\t\t\t\t$this->cfwBuf = '';\n\t\t\t}\n\t\t\treturn $written === false ? 0 : $written;\n\t\t}\n\n\t\t/**\n\t\t * A method this writer does not implement degrades with a reason and answers false.\n\t\t *\n\t\t * @param array<int, mixed> $args\n\t\t *   The arguments the caller passed.\n\t\t */\n\t\tpublic function __call(string $method, array $args): bool\n\t\t{\n\t\t\tif (class_exists(Degradation::class)) {\n\t\t\t\tDegradation::record(\n\t\t\t\t\t'xmlwriter.' . $method,\n\t\t\t\t\t'the XMLWriter stand-in does not implement ' . $method . '()',\n\t\t\t\t);\n\t\t\t}\n\t\t\treturn false;\n\t\t}\n\n\t\tpublic function __destruct()\n\t\t{\n\t\t\tif ($this->cfwHandle === null) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tif ($this->cfwBuf !== '') {\n\t\t\t\t@fwrite($this->cfwHandle, $this->cfwBuf);\n\t\t\t\t$this->cfwBuf = '';\n\t\t\t}\n\t\t\t@fclose($this->cfwHandle);\n\t\t\t$this->cfwHandle = null;\n\t\t}\n\n\t\t/** shared by openMemory() and openUri(); a reopen abandons whatever was in flight */\n\t\tprivate function cfwReset(): void\n\t\t{\n\t\t\t$this->cfwBuf = '';\n\t\t\t$this->cfwStack = [];\n\t\t\t$this->cfwOpen = false;\n\t\t\tif ($this->cfwHandle !== null) {\n\t\t\t\t@fclose($this->cfwHandle);\n\t\t\t\t$this->cfwHandle = null;\n\t\t\t}\n\t\t}\n\n\t\t/** finishes an open start tag, which is what makes attributes order-sensitive */\n\t\tprivate function cfwCloseStart(): void\n\t\t{\n\t\t\tif ($this->cfwOpen) {\n\t\t\t\t$this->cfwBuf .= '>';\n\t\t\t\t$this->cfwOpen = false;\n\t\t\t}\n\t\t}\n\n\t\t/**\n\t\t * A newline plus one indent per open element, never before the very first node, and never\n\t\t * doubled after the declaration -- which already ends its own line.\n\t\t */\n\t\tprivate function cfwNewline(): void\n\t\t{\n\t\t\tif (!$this->cfwIndent || $this->cfwBuf === '') {\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tif (substr($this->cfwBuf, -1) !== \"\\n\") {\n\t\t\t\t$this->cfwBuf .= \"\\n\";\n\t\t\t}\n\t\t\t$this->cfwBuf .= str_repeat($this->cfwIndentString, count($this->cfwStack));\n\t\t}\n\n\t\t/**\n\t\t * ONE escaper for both text and attributes, which is what libxml does.\n\t\t *\n\t\t * The obvious split -- ampersand and angle brackets in text, plus the double quote only in\n\t\t * attributes -- is wrong, measured: libxml escapes a double quote in TEXT content as well,\n\t\t * and leaves a single quote alone in both. Guessing produced exactly that split and the\n\t\t * oracle rejected it.\n\t\t */\n\t\tprivate function cfwEscape(string $s): string\n\t\t{\n\t\t\treturn str_replace(['&', '<', '>', '\"'], ['&amp;', '&lt;', '&gt;', '&quot;'], $s);\n\t\t}\n\t}\n}\n";

export const ZLIB_FIX_PHP = "\n// NO eval(), unlike mb-fix. A conditional declaration colliding with an internal function is\n// deferred to runtime, so this compiles clean on a build that HAS zlib and the branch simply\n// does not run -- verified with php -l plus a run on a host with the extension loaded. Plain\n// PHP is what lets tests/node/php-fragments.spec.ts see inside the body at all.\n\n// FIRST BLOCK: the bridge itself plus the one capability ext-zlib does not have. Nothing here\n// collides with an internal function, so it is declared on every build.\nif (!function_exists('cfw_zlib_dict')) {\n\t$__cfw_zlib = function_exists('vrzno_env') ? vrzno_env('cfwZlib') : null;\n\tif ($__cfw_zlib !== null) {\n\t\t$GLOBALS['__cfw_zlib'] = $__cfw_zlib;\n\n\t\t/**\n\t\t * Runs one op over the bridge.\n\t\t *\n\t\t * @param string $op\n\t\t *   gzip, gunzip, zlib, unzlib, deflate or inflate.\n\t\t * @param string $data\n\t\t *   The bytes to transform.\n\t\t * @param int $level\n\t\t *   A zlib level, or -1 for the default.\n\t\t * @param string $dict\n\t\t *   A preset dictionary, or an empty string for none.\n\t\t *\n\t\t * @return array{ok: bool, data?: string, error?: string}\n\t\t *   ['ok' => true, 'data' => string] or ['ok' => false, 'error' => string].\n\t\t */\n\t\tfunction cfw_zlib($op, $data, $level = -1, $dict = ''): array\n\t\t{\n\t\t\t$fn = $GLOBALS['__cfw_zlib'];\n\t\t\t$reply = json_decode(\n\t\t\t\t$fn(\n\t\t\t\t\tjson_encode([\n\t\t\t\t\t\t'op' => $op,\n\t\t\t\t\t\t'b64' => base64_encode((string) $data),\n\t\t\t\t\t\t'level' => $level,\n\t\t\t\t\t\t'dict' => base64_encode((string) $dict),\n\t\t\t\t\t]),\n\t\t\t\t),\n\t\t\t\ttrue,\n\t\t\t);\n\t\t\tif (!is_array($reply) || ($reply['ok'] ?? false) !== true) {\n\t\t\t\t$why = is_array($reply)\n\t\t\t\t\t? (string) ($reply['error'] ?? 'no reason given')\n\t\t\t\t\t: 'unreadable reply';\n\t\t\t\treturn ['ok' => false, 'error' => $why];\n\t\t\t}\n\t\t\t$out = base64_decode((string) ($reply['b64'] ?? ''), true);\n\t\t\tif ($out === false) {\n\t\t\t\treturn ['ok' => false, 'error' => 'reply was not base64'];\n\t\t\t}\n\t\t\treturn ['ok' => true, 'data' => $out];\n\t\t}\n\n\t\t/**\n\t\t * Raises the diagnostic ext-zlib raises, then answers FALSE like it does.\n\t\t *\n\t\t * @param string $name\n\t\t *   The PHP function that failed.\n\t\t * @param string $reason\n\t\t *   What ext-zlib would have said.\n\t\t */\n\t\tfunction cfw_zlib_fail($name, $reason): false\n\t\t{\n\t\t\ttrigger_error($name . '(): ' . $reason, E_USER_WARNING);\n\t\t\treturn false;\n\t\t}\n\n\t\t/**\n\t\t * Compresses or decompresses against a preset dictionary.\n\t\t *\n\t\t * NOT shaped like a gz* function: PHP has never had a dictionary\n\t\t * parameter on gzcompress(), so widening one of those signatures would make a host-only\n\t\t * argument look like part of the language. function_exists('cfw_zlib_dict') is the feature\n\t\t * test a caller uses.\n\t\t *\n\t\t * $op is 'zlib' to compress and 'unzlib' to decompress; the output is an ordinary zlib\n\t\t * stream with FDICT set. gzip and the raw pair are refused, because neither has anywhere\n\t\t * to record the dictionary's checksum -- so a wrong dictionary would decode to plausible\n\t\t * garbage instead of failing.\n\t\t *\n\t\t * @param string $op\n\t\t *   zlib or unzlib.\n\t\t * @param string $data\n\t\t *   The bytes to transform.\n\t\t * @param string $dict\n\t\t *   The preset dictionary.\n\t\t * @param int $level\n\t\t *   A zlib level, or -1 for the default.\n\t\t *\n\t\t * @return string|false\n\t\t *   The bytes, or FALSE with an E_USER_WARNING, matching the gz* functions.\n\t\t */\n\t\tfunction cfw_zlib_dict($op, $data, $dict, $level = -1)\n\t\t{\n\t\t\tif ($op !== 'zlib' && $op !== 'unzlib') {\n\t\t\t\treturn cfw_zlib_fail(\n\t\t\t\t\t'cfw_zlib_dict',\n\t\t\t\t\t\"op '\" .\n\t\t\t\t\t\t$op .\n\t\t\t\t\t\t\"' takes no preset dictionary; use zlib to compress or unzlib to decompress\",\n\t\t\t\t);\n\t\t\t}\n\t\t\tif ((string) $dict === '') {\n\t\t\t\treturn cfw_zlib_fail('cfw_zlib_dict', 'the dictionary is empty');\n\t\t\t}\n\t\t\t$r = cfw_zlib($op, $data, $level, $dict);\n\t\t\treturn $r['ok'] ? $r['data'] : cfw_zlib_fail('cfw_zlib_dict', $r['error']);\n\t\t}\n\t}\n}\n\n// SECOND BLOCK: the six names ext-zlib owns. Inert wherever the extension is loaded, which\n// includes the shipping binary.\nif (!extension_loaded('zlib') && !function_exists('cfw_zlib_installed')) {\n\t$__cfw_zlib = function_exists('vrzno_env') ? vrzno_env('cfwZlib') : null;\n\tif ($__cfw_zlib !== null) {\n\t\t$GLOBALS['__cfw_zlib'] = $__cfw_zlib;\n\n\t\t// ext-zlib declares these, so they vanish with it. FORCE_GZIP is read by AssetDumper and\n\t\t// would be an Error(\"Undefined constant\") without this line.\n\t\tif (!defined('ZLIB_ENCODING_RAW')) {\n\t\t\tdefine('ZLIB_ENCODING_RAW', -15);\n\t\t}\n\t\tif (!defined('ZLIB_ENCODING_DEFLATE')) {\n\t\t\tdefine('ZLIB_ENCODING_DEFLATE', 15);\n\t\t}\n\t\tif (!defined('ZLIB_ENCODING_GZIP')) {\n\t\t\tdefine('ZLIB_ENCODING_GZIP', 31);\n\t\t}\n\t\tif (!defined('FORCE_DEFLATE')) {\n\t\t\tdefine('FORCE_DEFLATE', 15);\n\t\t}\n\t\tif (!defined('FORCE_GZIP')) {\n\t\t\tdefine('FORCE_GZIP', 31);\n\t\t}\n\n\t\tfunction cfw_zlib_installed(): bool\n\t\t{\n\t\t\treturn true;\n\t\t}\n\n\t\t/**\n\t\t * Refuses a level outside -1..9, with the ValueError ext-zlib throws.\n\t\t *\n\t\t * @param string $name\n\t\t *   The PHP function being called.\n\t\t * @param int $level\n\t\t *   The level the caller passed.\n\t\t *\n\t\t * @return int\n\t\t *   The level, unchanged.\n\t\t */\n\t\tfunction cfw_zlib_level($name, $level)\n\t\t{\n\t\t\tif ($level < -1 || $level > 9) {\n\t\t\t\tthrow new ValueError($name . \"(): Argument #2 (\\$level) must be between -1 and 9\");\n\t\t\t}\n\t\t\treturn $level;\n\t\t}\n\n\t\t/**\n\t\t * The container an encoding names.\n\t\t *\n\t\t * All three encoders accept all three encodings and emit that container -- measured on\n\t\t * 8.5.7, gzcompress(x, 9, ZLIB_ENCODING_GZIP) is byte-identical to\n\t\t * gzencode(x, 9, FORCE_GZIP) -- so the three share one mapping.\n\t\t *\n\t\t * @param string $name\n\t\t *   The PHP function being called.\n\t\t * @param int $encoding\n\t\t *   A ZLIB_ENCODING_* value.\n\t\t */\n\t\tfunction cfw_zlib_encoding($name, $encoding): string\n\t\t{\n\t\t\tif ($encoding === 31) {\n\t\t\t\treturn 'gzip';\n\t\t\t}\n\t\t\tif ($encoding === 15) {\n\t\t\t\treturn 'zlib';\n\t\t\t}\n\t\t\tif ($encoding === -15) {\n\t\t\t\treturn 'deflate';\n\t\t\t}\n\t\t\tthrow new ValueError(\n\t\t\t\t$name .\n\t\t\t\t\t\"(): Argument #3 (\\$encoding) must be one of ZLIB_ENCODING_RAW, ZLIB_ENCODING_GZIP, or ZLIB_ENCODING_DEFLATE\",\n\t\t\t);\n\t\t}\n\n\t\t/**\n\t\t * Applies $max_length the way zlib does, which is NOT a truncation.\n\t\t *\n\t\t * Measured: gzuncompress(gzcompress('hello world'), 5) is FALSE, not 'hello'. zlib fails\n\t\t * the inflate when its output buffer is too small, so a cap below the payload is a data\n\t\t * error rather than a short read. 0 means no cap.\n\t\t *\n\t\t * @param string $name\n\t\t *   The PHP function being called.\n\t\t * @param string $data\n\t\t *   The inflated bytes.\n\t\t * @param int $max_length\n\t\t *   The cap, or 0 for none.\n\t\t *\n\t\t * @return string|false\n\t\t *   The bytes, or FALSE with an E_USER_WARNING when the cap was exceeded.\n\t\t */\n\t\tfunction cfw_zlib_cap($name, $data, $max_length)\n\t\t{\n\t\t\tif ($max_length > 0 && strlen($data) > $max_length) {\n\t\t\t\treturn cfw_zlib_fail($name, 'data error');\n\t\t\t}\n\t\t\treturn $data;\n\t\t}\n\n\t\t// the encoding defaults are spelled as ints rather than as the constants defined above, so\n\t\t// the signature does not depend on when a define() ran\n\t\t/**\n\t\t * @param string $data\n\t\t *   The bytes to compress.\n\t\t * @param int $level\n\t\t *   A zlib level, or -1 for the default.\n\t\t * @param int $encoding\n\t\t *   A ZLIB_ENCODING_* value.\n\t\t *\n\t\t * @return string|false\n\t\t */\n\t\tfunction gzencode($data, $level = -1, $encoding = 31)\n\t\t{\n\t\t\t$op = cfw_zlib_encoding('gzencode', $encoding);\n\t\t\tcfw_zlib_level('gzencode', $level);\n\t\t\t$r = cfw_zlib($op, $data, $level);\n\t\t\treturn $r['ok'] ? $r['data'] : cfw_zlib_fail('gzencode', $r['error']);\n\t\t}\n\n\t\t/**\n\t\t * @param string $data\n\t\t *   The bytes to compress.\n\t\t * @param int $level\n\t\t *   A zlib level, or -1 for the default.\n\t\t * @param int $encoding\n\t\t *   A ZLIB_ENCODING_* value.\n\t\t *\n\t\t * @return string|false\n\t\t */\n\t\tfunction gzcompress($data, $level = -1, $encoding = 15)\n\t\t{\n\t\t\t$op = cfw_zlib_encoding('gzcompress', $encoding);\n\t\t\tcfw_zlib_level('gzcompress', $level);\n\t\t\t$r = cfw_zlib($op, $data, $level);\n\t\t\treturn $r['ok'] ? $r['data'] : cfw_zlib_fail('gzcompress', $r['error']);\n\t\t}\n\n\t\t/**\n\t\t * @param string $data\n\t\t *   The bytes to compress.\n\t\t * @param int $level\n\t\t *   A zlib level, or -1 for the default.\n\t\t * @param int $encoding\n\t\t *   A ZLIB_ENCODING_* value.\n\t\t *\n\t\t * @return string|false\n\t\t */\n\t\tfunction gzdeflate($data, $level = -1, $encoding = -15)\n\t\t{\n\t\t\t$op = cfw_zlib_encoding('gzdeflate', $encoding);\n\t\t\tcfw_zlib_level('gzdeflate', $level);\n\t\t\t$r = cfw_zlib($op, $data, $level);\n\t\t\treturn $r['ok'] ? $r['data'] : cfw_zlib_fail('gzdeflate', $r['error']);\n\t\t}\n\n\t\t/**\n\t\t * @param string $data\n\t\t *   The gzip stream.\n\t\t * @param int $max_length\n\t\t *   The cap on the inflated size, or 0 for none.\n\t\t *\n\t\t * @return string|false\n\t\t */\n\t\tfunction gzdecode($data, $max_length = 0)\n\t\t{\n\t\t\t$r = cfw_zlib('gunzip', $data);\n\t\t\tif (!$r['ok']) {\n\t\t\t\treturn cfw_zlib_fail('gzdecode', 'data error');\n\t\t\t}\n\t\t\treturn cfw_zlib_cap('gzdecode', $r['data'], $max_length);\n\t\t}\n\n\t\t/**\n\t\t * @param string $data\n\t\t *   The zlib stream.\n\t\t * @param int $max_length\n\t\t *   The cap on the inflated size, or 0 for none.\n\t\t *\n\t\t * @return string|false\n\t\t */\n\t\tfunction gzuncompress($data, $max_length = 0)\n\t\t{\n\t\t\t$r = cfw_zlib('unzlib', $data);\n\t\t\tif (!$r['ok']) {\n\t\t\t\treturn cfw_zlib_fail('gzuncompress', 'data error');\n\t\t\t}\n\t\t\treturn cfw_zlib_cap('gzuncompress', $r['data'], $max_length);\n\t\t}\n\n\t\t/**\n\t\t * @param string $data\n\t\t *   The raw deflate stream.\n\t\t * @param int $max_length\n\t\t *   The cap on the inflated size, or 0 for none.\n\t\t *\n\t\t * @return string|false\n\t\t */\n\t\tfunction gzinflate($data, $max_length = 0)\n\t\t{\n\t\t\t$r = cfw_zlib('inflate', $data);\n\t\t\tif (!$r['ok']) {\n\t\t\t\treturn cfw_zlib_fail('gzinflate', 'data error');\n\t\t\t}\n\t\t\treturn cfw_zlib_cap('gzinflate', $r['data'], $max_length);\n\t\t}\n\t}\n}\n";
